WITH product_summary AS (SELECT product_id, COUNT(DISTINCT quantity) AS unique_orders, MIN(quantity) AS min_quantity FROM order_items WHERE product_id = 27 GROUP BY product_id) SELECT products.id, products.brand, products.cost, product_summary.unique_orders, product_summary.min_quantity FROM products INNER JOIN product_summary ON products.id = product_summary.product_id WHERE product_summary.min_quantity >= 5.7 ORDER BY products.id DESC
